 const seen=new Set(),todo=Object.values(n).flat();
 while(todo.length){const c=todo.pop();if(!c||seen.has(c))continue;seen.add(c);todo.push(...n.$siblings(c),...refs(c).map(r=>n.$ref(r)).filter(Boolean));}
